const t0 = performance.now();
let found = -1;
for (let s = 0; s < 1000000; s++) {
  let a = ((s ^ 0xa5a5a5a5) + 0x6d2b79f5 * 4) >>> 0;
  let t1 = Math.imul(a ^ (a >>> 15), a | 1);
  t1 ^= t1 + Math.imul(t1 ^ (t1 >>> 7), t1 | 61);
  let r4 = ((t1 ^ (t1 >>> 14)) >>> 0);
  a = (a + 0x6d2b79f5) >>> 0;
  let t2 = Math.imul(a ^ (a >>> 15), a | 1);
  t2 ^= t2 + Math.imul(t2 ^ (t2 >>> 7), t2 | 61);
  let r5 = ((t2 ^ (t2 >>> 14)) >>> 0);
  a = (a + 0x6d2b79f5) >>> 0;
  let t3 = Math.imul(a ^ (a >>> 15), a | 1);
  t3 ^= t3 + Math.imul(t3 ^ (t3 >>> 7), t3 | 61);
  let r6 = ((t3 ^ (t3 >>> 14)) >>> 0);
  if (r4 + r5 + r6 === 1234567) found = s;
}
