  function evalSpline(t, p0) {
    const times = [0, 1.75, 3.5, 5.25, 7.0];
    const pts = [
      p0,
      GATES[0].centre,
      GATES[1].centre,
      GATES[2].centre,
      { x: PAD.centre.x, y: 0.082, z: PAD.centre.z }
    ];
    const vels = [
      { x: 0, y: 0, z: 0 },
      { x: 0.9, y: 0, z: 0 },
      { x: 0.9, y: 0, z: 0 },
      { x: 0.9, y: 0, z: 0 },
      { x: 0, y: 0, z: 0 }
    ];
    if (t >= 7.0) {
      return { pos: { ...pts[4] }, vel: { x: 0, y: 0, z: 0 }, acc: { x: 0, y: 0, z: 0 } };
    }
    let k = 0;
    while (k < 3 && t >= times[k + 1]) k++;
    const T = times[k + 1] - times[k];
    const u = clamp((t - times[k]) / T, 0, 1);
    const u2 = u * u, u3 = u2 * u;
    const h00 = 2 * u3 - 3 * u2 + 1;
    const h10 = u3 - 2 * u2 + u;
    const h01 = -2 * u3 + 3 * u2;
    const h11 = u3 - u2;

    const dh00 = 6 * u2 - 6 * u;
    const dh10 = 3 * u2 - 4 * u + 1;
    const dh01 = -6 * u2 + 6 * u;
    const dh11 = 3 * u2 - 2 * u;

    const d2h00 = 12 * u - 6;
    const d2h10 = 6 * u - 4;
    const d2h01 = -12 * u + 6;
    const d2h11 = 6 * u - 2;

    const pos = {}, vel = {}, acc = {};
