      const pk = pts[k][ax], pk1 = pts[k + 1][ax];
      const mk = T * vels[k][ax], mk1 = T * vels[k + 1][ax];
      pos[ax] = h00 * pk + h10 * mk + h01 * pk1 + h11 * mk1;
      vel[ax] = (dh00 * pk + dh10 * mk + dh01 * pk1 + dh11 * mk1) / T;
      acc[ax] = (d2h00 * pk + d2h10 * mk + d2h01 * pk1 + d2h11 * mk1) / (T * T);
