      }
    }
    return w;
  }

  function previewWind(params, t, tStart, tEnd, samples = 9) {
    const w = { x: 0, y: 0, z: 0 };
    for (let i = 0; i < samples; i++) {
      const tau = tStart + (i / (samples - 1)) * (tEnd - tStart);
      const wt = windAt(params, t + tau);
      w.x += wt.x / samples; w.y += wt.y / samples; w.z += wt.z / samples;
    }
