        t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
        sum += (t ^ (t >>> 14)) >>> 0;
        if (sum >= loX && sum <= hiX) {
          a = (a + 0x6d2b79f5) >>> 0;
          t = Math.imul(a ^ (a >>> 15), a | 1);
          t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
          let sumY = (t ^ (t >>> 14)) >>> 0;
          a = (a + 0x6d2b79f5) >>> 0;
